{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "Ensure all data stored in the EBS is securely encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The EBS volume has 'encrypted' explicitly set to false, leaving data at rest unencrypted and vulnerable to compromise if the underlying storage media is accessed."
    },
    {
      "check_id": "AVD-AWS-0026",
      "title": "EBS volume is not encrypted.",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "Unencrypted sensitive data on EBS volumes is a significant security risk. The current configuration disables encryption entirely."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n}",
  "fix_summary": "Changed the 'encrypted' attribute from false to true to enable encryption for the EBS volume, addressing both CKV_AWS_3 and AVD-AWS-0026 findings."
}
